def brackets_are_balanced(text):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for character in text:
        if character in pairs.values():
            stack.append(character)
        elif character in pairs:
            if not stack or stack.pop() != pairs[character]:
                return False
    return not stack

function bracketsAreBalanced(text) {
  const pairs = { ')': '(', ']': '[', '}': '{' }
  const openings = new Set(Object.values(pairs))
  const stack = []
  for (const character of text) {
    if (openings.has(character)) stack.push(character)
    else if (character in pairs && stack.pop() !== pairs[character]) return false
  }
  return stack.length === 0
}

def evaluate_postfix(tokens):
    operations = {
        "+": lambda a, b: a + b,
        "-": lambda a, b: a - b,
        "*": lambda a, b: a * b,
        "/": lambda a, b: int(a / b),
    }
    stack = []
    for token in tokens:
        if token not in operations:
            stack.append(int(token))
            continue
        right = stack.pop()
        left = stack.pop()
        stack.append(operations[token](left, right))
    return stack.pop()

function evaluatePostfix(tokens) {
  const operations = {
    '+': (a, b) => a + b,
    '-': (a, b) => a - b,
    '*': (a, b) => a * b,
    '/': (a, b) => Math.trunc(a / b)
  }
  const stack = []
  for (const token of tokens) {
    if (!(token in operations)) {
      stack.push(Number(token))
      continue
    }
    const right = stack.pop()
    const left = stack.pop()
    stack.push(operations[token](left, right))
  }
  return stack.pop()
}

def next_greater_elements(numbers):
    result = [-1] * len(numbers)
    stack = []
    for index, number in enumerate(numbers):
        while stack and numbers[stack[-1]] < number:
            previous = stack.pop()
            result[previous] = number
        stack.append(index)
    return result

function nextGreaterElements(numbers) {
  const result = new Array(numbers.length).fill(-1)
  const stack = []
  for (let index = 0; index < numbers.length; index++) {
    while (stack.length && numbers[stack[stack.length - 1]] < numbers[index]) {
      const previous = stack.pop()
      result[previous] = numbers[index]
    }
    stack.push(index)
  }
  return result
}

class QueueWithStacks:
    def __init__(self):
        self.input = []
        self.output = []

    def enqueue(self, value):
        self.input.append(value)

    def dequeue(self):
        if not self.output:
            while self.input:
                self.output.append(self.input.pop())
        if not self.output:
            raise IndexError("dequeue from empty queue")
        return self.output.pop()

