class MinStack:
    def __init__(self):
        self.values = []
        self.minimums = []

    def push(self, value):
        self.values.append(value)
        current = value if not self.minimums else min(value, self.minimums[-1])
        self.minimums.append(current)

    def pop(self):
        self.minimums.pop()
        return self.values.pop()

    def get_minimum(self):
        return self.minimums[-1]

class MinStack {
  constructor() {
    this.values = []
    this.minimums = []
  }

  push(value) {
    this.values.push(value)
    const previous = this.minimums[this.minimums.length - 1]
    this.minimums.push(previous === undefined ? value : Math.min(value, previous))
  }

  pop() {
    this.minimums.pop()
    return this.values.pop()
  }

  getMinimum() {
    return this.minimums[this.minimums.length - 1]
  }
}
